fn dims() -> i32 {
    (240 << 16) | 400
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let band: i32 = h / 16;
    let mut i: i32 = 0;
    while i < 16 {
        let blue: i32 = 32 + i * 14;
        host::display::fill_rect(0, i * band, w, band, blue);
        i = i + 1;
    }
    host::display::present();
}
